import React, { useEffect, useRef, useState } from "react";
import api from "../services/api";

const formatResourceLabel = (resource) =>
  resource.floor ? `${resource.name} - ${resource.floor}` : resource.name;

const BookingForm = ({
  formData,
  onChange,
  onSubmit,
  onAvailabilityCheck,
  availabilityMsg,
  loading
}) => {
  const [blocks, setBlocks] = useState([]);
  const [blocksCache, setBlocksCache] = useState([]);
  const [resources, setResources] = useState([]);
  const [cachedResources, setCachedResources] = useState({});
  const [blocksLoading, setBlocksLoading] = useState(false);
  const [resourceLoading, setResourceLoading] = useState(false);
  const blocksFetchedRef = useRef(false);

  useEffect(() => {
    const fetchBlocks = async () => {
      if (blocksFetchedRef.current) {
        return;
      }

      if (blocksCache.length > 0) {
        setBlocks(blocksCache);
        return;
      }

      blocksFetchedRef.current = true;
      setBlocksLoading(true);
      try {
        const response = await api.get("/blocks");
        console.log("Blocks API response:", response.data);
        const nextBlocks = response.data || [];
        setBlocks(nextBlocks);
        setBlocksCache(nextBlocks);
      } catch (err) {
        console.log(err);
        setBlocks([]);
      } finally {
        setBlocksLoading(false);
      }
    };

    fetchBlocks();
  }, [blocksCache]);

  useEffect(() => {
    if (formData.resourceScope === "block" && !formData.blockId) {
      setResources([]);
      setResourceLoading(false);
      return undefined;
    }

    const cacheKey = formData.resourceScope === "extra" ? "extra" : formData.blockId;
    if (cachedResources[cacheKey]) {
      setResources(cachedResources[cacheKey]);
      setResourceLoading(false);
      return undefined;
    }

    setResourceLoading(true);
    const timeoutId = window.setTimeout(async () => {
      setResourceLoading(true);
      try {
        const response =
          formData.resourceScope === "extra"
            ? await api.get("/extra-centers")
            : await api.get(`/blocks/${formData.blockId}/resources`);
        const nextResources = response.data || [];
        setResources(nextResources);
        setCachedResources((previous) => ({
          ...previous,
          [cacheKey]: nextResources
        }));
      } catch {
        setResources([]);
      } finally {
        setResourceLoading(false);
      }
    }, 250);

    return () => window.clearTimeout(timeoutId);
  }, [cachedResources, formData.blockId, formData.resourceScope]);

  const handleScopeChange = (value) => {
    onChange({ target: { name: "resourceScope", value } });
    onChange({ target: { name: "blockId", value: "" } });
    onChange({ target: { name: "resourceId", value: "" } });
  };

  const handleBlockChange = (event) => {
    onChange({ target: { name: "blockId", value: event.target.value } });
    onChange({ target: { name: "resourceId", value: "" } });
  };

  const scopeIsBlock = formData.resourceScope === "block";

  return (
    <div className="panel-card booking-card-shell">
      <div className="panel-header">
        <div>
          <h3>Create Booking</h3>
          <p>Pick a block or extra center, choose a resource, and reserve your slot.</p>
        </div>
      </div>

      <div className="scope-toggle">
        <button
          type="button"
          className={`scope-chip ${scopeIsBlock ? "active" : ""}`}
          onClick={() => handleScopeChange("block")}
        >
          Block
        </button>
        <button
          type="button"
          className={`scope-chip ${!scopeIsBlock ? "active" : ""}`}
          onClick={() => handleScopeChange("extra")}
        >
          Extra Centers
        </button>
      </div>

      {blocksLoading ? <div className="skeleton-line" aria-hidden="true" /> : null}

      <form className="grid-form" onSubmit={onSubmit}>
        {scopeIsBlock ? (
          <label>
            <span>Block</span>
            <select value={formData.blockId || ""} onChange={handleBlockChange} required disabled={blocksLoading}>
              <option value="">
                {blocksLoading ? "Loading blocks..." : blocks.length === 0 ? "No blocks available" : "Select block"}
              </option>
              {blocks.map((block) => (
                <option key={block.id} value={block.id}>
                  Block {block.name}
                </option>
              ))}
            </select>
          </label>
        ) : (
          <div className="selection-summary">
            <span>Extra Centers</span>
            <p>Book shared spaces like the Innovation Center or Main Seminar Hall.</p>
          </div>
        )}

        <label>
          <span>Resource</span>
          <select
            name="resourceId"
            value={formData.resourceId || ""}
            onChange={onChange}
            required
            disabled={resourceLoading || (scopeIsBlock ? !formData.blockId : false)}
          >
            <option value="">
              {scopeIsBlock && !formData.blockId
                ? "Select block first"
                : resourceLoading
                ? "Loading resources..."
                : resources.length === 0
                ? "No resources found"
                : "Select resource"}
            </option>
            {resources.map((resource) => (
              <option key={resource.id} value={resource.id}>
                {formatResourceLabel(resource)}
              </option>
            ))}
          </select>
        </label>

        {resourceLoading ? <div className="skeleton-line full-width" aria-hidden="true" /> : null}

        <label>
          <span>Date</span>
          <input
            type="date"
            name="bookingDate"
            value={formData.bookingDate || ""}
            onChange={onChange}
            required
          />
        </label>

        <label>
          <span>Start time</span>
          <input
            type="time"
            name="startTime"
            value={formData.startTime || ""}
            onChange={onChange}
            required
          />
        </label>

        <label>
          <span>End time</span>
          <input
            type="time"
            name="endTime"
            value={formData.endTime || ""}
            onChange={onChange}
            required
          />
        </label>

        <label className="full-width">
          <span>Purpose</span>
          <textarea
            name="purpose"
            value={formData.purpose || ""}
            onChange={onChange}
            rows="4"
            placeholder="Add purpose for this booking"
          />
        </label>

        <div className="form-actions full-width">
          <button type="button" className="secondary-button" onClick={onAvailabilityCheck} disabled={loading || resourceLoading}>
            {resourceLoading ? "Loading Resources..." : "Check Availability"}
          </button>
          <button type="submit" className="primary-button" disabled={loading}>
            {loading ? "Submitting..." : "Create Booking"}
          </button>
        </div>

        {availabilityMsg ? (
          <div className="alert-box full-width">
            {String(availabilityMsg)}
          </div>
        ) : null}
      </form>
    </div>
  );
};

export default BookingForm;
